// Original procedural pixel art: cached village tiles plus animated lights and sprites.
const VIEW={w:960,h:640};let villageFloor;let cameraZoom=1;try{cameraZoom=Math.max(.65,Math.min(2.4,Number(localStorage.getItem('giwa-camera-zoom'))||1))}catch{}
function resizeGame(){const scale=Math.max(.38,Math.min(1,window.innerWidth/1920))*cameraZoom;VIEW.w=Math.round(window.innerWidth/scale);VIEW.h=Math.round(window.innerHeight/scale);canvas.width=VIEW.w;canvas.height=VIEW.h;ctx.imageSmoothingEnabled=false;}
window.addEventListener('resize',resizeGame);resizeGame();
let artSeed=479;function ar(){artSeed=(artSeed*16807)%2147483647;return(artSeed-1)/2147483646}
function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fill()}
function disc(x,y,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function glow(x,y,r,color){const g=ctx.createRadialGradient(x,y,2,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'#ffb54a00');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
function stonePatch(x,y,w,h){rect(x-3,y-3,w+6,h+6,'#293448');for(let row=0;row<h/15;row++)for(let col=-1;col<w/23+1;col++){let xx=x+col*23+(row%2)*11,yy=y+row*15;let ww=Math.min(21,x+w-xx);if(xx<x){ww-=x-xx;xx=x}if(ww<1)continue;rect(xx,yy,ww,13,['#687087','#707a91','#626c84','#7b8198'][Math.floor(ar()*4)]);rect(xx+1,yy+1,Math.max(1,ww-2),1,'#9a9db155');rect(xx+1,yy+11,Math.max(1,ww-2),2,'#3f4b6355')}}
function tree(t){let{x,y,s=1}=t;ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(s,s);shadow(0,4,30);polygon([[-9,8],[-4,-49],[7,-48],[9,8],[3,4],[-1,9]],'#243d37');rect(-3,-48,7,52,'#6e6850');rect(-1,-40,2,41,'#a08c63');polygon([[-4,-20],[-20,-41],[-18,-46],[1,-32],[20,-51],[23,-44],[6,-22]],'#706c4f');
 const crowns=[[-22,-61,22],[-6,-80,24],[19,-66,25],[3,-56,30]];crowns.forEach(([a,b,r],i)=>{polygon([[a-r,b-7],[a-r+3,b-17],[a-13,b-r],[a+4,b-r-3],[a+r-5,b-16],[a+r,b+2],[a+r-6,b+14],[a+7,b+r-4],[a-13,b+r-8],[a-r-4,b+5]],'#123d3f');disc(a,b-5,r-4,['#225d4b','#34774f','#276a51','#215849'][i]);disc(a-6,b-12,r*.57,['#357a55','#4b8a59','#3e8057','#2f6b50'][i]);for(let k=0;k<8;k++){let xx=a+Math.sin(k*2.8+i)*r*.65,yy=b+Math.cos(k*3.7)*r*.6;rect(xx,yy,4,2,k%2?'#61906088':'#153f3f88')}});ctx.restore()}
function person(x,y,npc=false){x=Math.round(x);y=Math.round(y);let moving=!npc&&(keys.w||keys.a||keys.s||keys.d||keys.arrowup||keys.arrowleft||keys.arrowdown||keys.arrowright),step=moving?Math.sin(time*14)*3:0;shadow(x,y,13);rect(x-8,y-8,6,8+step,'#202c46');rect(x+3,y-8,6,8-step,'#202c46');rect(x-9,y-2+step,7,3,'#4a3d43');rect(x+3,y-2-step,8,3,'#4a3d43');polygon([[x-12,y-31],[x-7,y-35],[x+8,y-35],[x+13,y-25],[x+10,y-10],[x-10,y-10]],npc?'#456c86':'#314d88');rect(x-8,y-28,16,16,npc?'#648397':'#5277b1');rect(x-4,y-29,3,17,npc?'#95afb0':'#839fce');rect(x-10,y-13,21,4,'#6c4953');rect(x-1,y-13,4,4,'#ddbd78');rect(x-14,y-28,5,13,npc?'#547589':'#6e87aa');rect(x+10,y-28,5,13,'#536888');rect(x-14,y-17,5,5,'#c59d7c');rect(x+10,y-17,5,5,'#c59d7c');rect(x-8,y-46,17,14,'#d1a784');rect(x-8,y-47,17,5,npc?'#654a47':'#8c8fa6');rect(x-10,y-43,4,10,npc?'#654a47':'#67798e');rect(x+5,y-40,2,3,'#252f42');rect(x-3,y-34,6,2,'#a77b69');if(!npc){rect(x-10,y-50,20,6,'#3c526b');rect(x-6,y-53,12,4,'#647f95');rect(x-4,y-52,5,3,'#b5c5c4');rect(x-12,y-31,8,6,'#a3b3b9');rect(x+6,y-31,8,6,'#92a6b2');rect(x+17,y-37,3,30,'#b9d9dc');rect(x+18,y-36,1,27,'#f0f4d7');rect(x+13,y-11,11,3,'#b99a62');rect(x+17,y-8,3,7,'#674746')}else{rect(x-12,y-49,24,4,'#a38a67');rect(x-7,y-57,15,9,'#725758');rect(x-5,y-55,11,3,'#a8876c')}}
function arch(x,y,color,locked=false){shadow(x,y+9,48);polygon([[x-45,y+6],[x-45,y-65],[x-35,y-91],[x-15,y-108],[x+15,y-108],[x+35,y-91],[x+45,y-65],[x+45,y+6]],'#172d42');polygon([[x-36,y],[x-36,y-65],[x-24,y-87],[x,y-99],[x+24,y-87],[x+36,y-65],[x+36,y]],'#8594a5');ctx.fillStyle=locked?'#44364f':'#14434b';ctx.beginPath();ctx.ellipse(x,y-42,28,49,0,0,Math.PI*2);ctx.fill();for(let i=0;i<10;i++){let a=Math.PI+i*Math.PI/9;ctx.strokeStyle='#34465e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+Math.cos(a)*30,y-63+Math.sin(a)*30);ctx.lineTo(x+Math.cos(a)*43,y-63+Math.sin(a)*43);ctx.stroke()}for(let yy=y-58;yy<y;yy+=15){rect(x-43,yy,14,2,'#425672');rect(x+29,yy,14,2,'#425672')}
 ctx.save();ctx.beginPath();ctx.ellipse(x,y-42,27,48,0,0,7);ctx.clip();disc(x,y-42,48,locked?'#594271':'#24745f');for(let i=0;i<4;i++){ctx.strokeStyle=locked?['#8668b1','#5d4f8b','#a18ac4','#6a599f'][i]:['#c8ef83','#68cda6','#ecf5b1','#42b7a2'][i];ctx.lineWidth=6-i;ctx.beginPath();for(let a=0;a<Math.PI*3;a+=.13){let r=a*3.6,aa=a+time*(locked?.35:1.1)+i*1.57,xx=x+Math.cos(aa)*r,yy=y-42+Math.sin(aa)*r*1.5;a?ctx.lineTo(xx,yy):ctx.moveTo(xx,yy)}ctx.stroke()}ctx.restore();rect(x-51,y+3,102,9,'#a9afb3');rect(x-56,y+12,112,6,'#697c8e');if(!locked)glow(x,y-40,68,'#b4ee6d24');}
function lamp(x,y){shadow(x,y,10);rect(x-5,y-4,10,6,'#20394b');rect(x-2,y-63,4,61,'#213b50');rect(x,y-60,1,51,'#6b8193');rect(x-9,y-72,18,4,'#192d42');rect(x-6,y-69,12,15,'#9e7849');rect(x-3,y-67,7,11,'#f4c06a');rect(x-1,y-66,3,9,'#fff2b0');polygon([[x-10,y-73],[x,y-80],[x+10,y-73]],'#38516a');glow(x,y-61,63,'#ffbf633c')}
