function planter(x,y){shadow(x,y+8,15);rect(x-14,y-3,28,15,'#3a4359');rect(x-16,y-5,32,5,'#a0a097');rect(x-12,y+2,24,2,'#6f7788');for(let i=0;i<6;i++){disc(x+Math.sin(i*3)*11,y-7+Math.cos(i*2)*4,6,'#397a59');rect(x+Math.sin(i*2)*9,y-14+Math.cos(i*3)*4,3,3,i%2?'#9e86bd':'#dbbbcf')}}
